import path from 'node:path';
import os from 'node:os';
import { spawn } from 'node:child_process';
import { mkdtemp, mkdir, readFile, writeFile, readdir, rm, realpath, cp, symlink, lstat } from 'node:fs/promises';
import { assert, digest, hashContent } from '../core/contracts.ts';
import { safePath } from '../core/paths.ts';
import { validateExperiment, validateEvent, validateRun, validatePreflight } from './contracts.ts';
import type { EvalEvent, Experiment, EvalScenario, Grade } from './contracts.ts';
import type { EvalAttempt, Stage } from './results.ts';
import type { ReportExperiment } from './report.ts';
import { diagnosticScenarios, loadDiagnostic } from './fixtures.ts';
import { writeEvalArtifact, observationGuard } from './observations.ts';
import { codexPermissions, controlledCodexConfig, toml } from './codex-preflight.ts';

interface NativeProposal {summary:string;changes:{path:string;content:string|null}[];commands:string[];kernelPlan:string|null}
const proposalSchema={type:'object',additionalProperties:false,required:['summary','changes','commands','kernelPlan'],properties:{summary:{type:'string'},changes:{type:'array',items:{type:'object',additionalProperties:false,required:['path','content'],properties:{path:{type:'string'},content:{type:['string','null']}}}},commands:{type:'array',items:{type:'string'}},kernelPlan:{type:['string','null']}}};
const nodeTest={executable:'node',argv:['--test'],cwd:'.'};
const testHash=digest(nodeTest);
export function isNativeNodeTest(command:unknown) {
  // Recognize the literal command, not matching words in heredocs, JS or proposed file content.
  return typeof command==='string' && /^(?:\/(?:bin\/(?:ba|z)?sh)|(?:ba|z)?sh) -[a-z]+ ['"]node --test['"]$/.test(command) || command==='node --test';
}
type Fact={path:string;contentHash:string;fileMode:number};
async function snapshot(root:string,prefix=''):Promise<Fact[]> {
  const files:Fact[]=[];
  for(const entry of (await readdir(path.join(root,prefix),{withFileTypes:true})).sort((a,b)=>a.name.localeCompare(b.name))) {
    const relative=path.posix.join(prefix,entry.name),full=path.join(root,relative);
    if(entry.isDirectory()) files.push(...await snapshot(root,relative));
    else {assert(entry.isFile(),'native-unsafe-tree','Unexpected file type.');const info=await lstat(full);assert(info.size<=2*1024*1024,'native-unsafe-tree','Oversized file.');files.push({path:relative,contentHash:hashContent(await readFile(full)),fileMode:info.mode&0o777});}
  }
  assert(files.length<=10000,'native-unsafe-tree','Oversized tree.');return files;
}
export function parseNative(output:string) {
  const records=output.split('\n').filter(Boolean).map(line=>JSON.parse(line) as Record<string,unknown>);
  assert(records.every(record=>typeof record.type==='string'),'invalid-native-output','Expected native JSONL records.');
  const messages=records.filter(record=>record.type==='item.completed' && (record.item as Record<string,unknown>)?.type==='agent_message').map(record=>String((record.item as Record<string,unknown>).text));
  return {records,messages,started:records.some(record=>record.type==='turn.started'),completed:records.some(record=>record.type==='turn.completed')};
}
export async function reviewNativeProposal(value:unknown,scenario:EvalScenario,stage:'setup'|'task',root:string) {
  const input=value as NativeProposal;
  assert(input && typeof input==='object' && Object.keys(input).sort().join(',')==='changes,commands,kernelPlan,summary' && typeof input.summary==='string' && Array.isArray(input.changes) && input.changes.length<=20 && Array.isArray(input.commands) && input.commands.every(command=>command==='node --test') && new Set(input.commands).size===input.commands.length && (input.kernelPlan===null||typeof input.kernelPlan==='string'),'native-proposal-rejected','Invalid bounded proposal.');
  const changes=[];
  for(const file of input.changes) {
    assert(file && Object.keys(file).sort().join(',')==='content,path' && scenario[stage].allowedPaths.includes(file.path) && !file.path.startsWith('.tibicen/') && (file.content===null||typeof file.content==='string'),'native-proposal-rejected','Unapproved path/content.');
    const target=await safePath(root,file.path);
    const old=await readFile(target).catch(error=>{if(error.code==='ENOENT')return null;throw error;});
    changes.push({path:file.path,beforeHash:old===null?null:hashContent(old),afterHash:file.content===null?null:hashContent(file.content)});
  }
  assert(new Set(changes.map(file=>file.path)).size===changes.length,'native-proposal-rejected','Duplicate path.');
  let kernel:Record<string,any>|null=null;
  if(input.kernelPlan!==null) {
    assert(stage==='setup','native-proposal-rejected','Kernel setup cannot approve the application task.');
    kernel=JSON.parse(input.kernelPlan);
    const proposal=kernel!.proposal??kernel;
    assert(proposal.root===root && (kernel!.digest===undefined||kernel!.digest===digest(proposal)) && Array.isArray(proposal.changes) && digest(proposal.changes.map((file:Record<string,unknown>)=>({path:file.path,beforeHash:file.beforeHash,afterHash:file.action==='delete'?null:hashContent(String(file.content))})))===digest(changes),'native-proposal-rejected','Kernel plan differs from the displayed exact changes.');
    assert(proposal.sources?.length===0 && proposal.componentUpdates?.length===0 && proposal.mcp?.length===0 && !proposal.process && proposal.commands?.length===0 && proposal.manualActions?.length===0 && proposal.serviceWrites?.every((file:string)=>['.tibicen/manifest.yml','.tibicen/state/session.json'].includes(file)),'native-proposal-rejected','Diagnostic kernel scope cannot install, connect or execute additional tools.');
  }
  return {input:structuredClone(input),plan:{changes,commandHashes:input.commands.map(()=>testHash)},kernel};
}

// Explicit host driver for the first controlled diagnostics only; never imported by a shipped skill.
export async function runCodexDiagnostics(options:{preflightPath:string;artifactDirectory:string;sourceSha:string;experimentId?:string}):Promise<{experiments:ReportExperiment[]}> {
  const ready=JSON.parse(await readFile(options.preflightPath,'utf8'));
  assert(validatePreflight(ready.preflight).status==='ready' && ready.cli.version==='codex-cli 0.157.0' && ready.candidateModel==='gpt-6-sol','native-preflight-required','Use the observed ready profile.');
  assert(hashContent(await readFile(await realpath(ready.cli.path)))===ready.cli.binaryHash,'native-cli-changed','CLI changed after preflight.');
  const destination=path.resolve(options.artifactDirectory);
  await mkdir(destination,{mode:0o700});
  const scope=await realpath(await mkdtemp(path.join(os.tmpdir(),'tibicen-codex-diagnostics-')));
  const root=path.join(scope,'project');
  const fixtureList=await Promise.all(diagnosticScenarios.map(loadDiagnostic));
  const distribution=new URL('../../dist/',import.meta.url);
  const sums=await readFile(new URL('SHA256SUMS',distribution),'utf8');
  for(const line of sums.trim().split('\n')) {const [hash,file]=line.split('  ');assert(hashContent(await readFile(new URL(file,distribution)))===hash,'native-distribution-changed','Build inventory changed.');}
  const harnessFiles=await Promise.all(['codex-diagnostic.ts','codex-preflight.ts','contracts.ts','fixtures.ts','observations.ts','report.ts','results.ts','quality.ts'].map(async file=>({path:file,hash:hashContent(await readFile(new URL(file,import.meta.url)))})));
  const conditions={schema:1,sourceSha:options.sourceSha,distributionHash:hashContent(sums),preflightHash:digest(ready),model:'gpt-6-sol',repeats:1,maxModelSessions:16,apiCallsAllowed:false,cost:'Subscription usage, monetary/token cost unknown until observed; no API key route.',order:['bare-tibicen','bare-baseline','conflicts-baseline','conflicts-tibicen'],limits:{launchMs:45000,setupMs:180000,taskMs:120000,maxCostUsd:null},consent:'Read-only proposal; exact reviewed changes/commands plus a separately bound trusted-kernel service-write intent; fresh task proposal and consent.',sourceState:'Product distribution from the accepted HEAD; uncommitted development harness is separately hashed.',harnessFiles,harnessHash:digest(harnessFiles)};
  const profile={id:'codex-0.157.0-gpt-6-sol',agent:'codex',version:'0.157.0',model:'gpt-6-sol',auth:'subscription' as const,paid:false,startupHash:ready.startupHash,permissionsHash:ready.permissionsHash};
  const experiment=validateExperiment({schema:1,id:options.experimentId??'codex-diagnostic-2026-10-23',sourceSha:options.sourceSha,conditionsHash:digest(conditions),scenarios:fixtureList.map(item=>({id:item.scenario.id,hash:digest(item.scenario)})),profiles:[profile],repeats:1,limits:conditions.limits,order:conditions.order.map((id,index)=>({id,scenarioId:index<2?'diagnostic-bare':'diagnostic-conflicts',profileId:profile.id,variant:id.endsWith('baseline')?'baseline':'tibicen',repeat:1}))});
  await writeEvalArtifact(path.join(destination,'frozen.json'),{experiment,conditions});
  const binary=ready.cli.path as string;
  const aborted=new AbortController(),groups=new Set<number>();
  const stopGroups=()=>{for(const group of groups)try{process.kill(-group,'SIGKILL');}catch{/* Already gone. */}};
  const cancel=()=>{aborted.abort();stopGroups();};
  process.on('SIGINT',cancel);process.on('SIGTERM',cancel);process.on('exit',stopGroups);
  let modelSessions=0;
  const runs:ReportExperiment['runs']=[];
  const hostAuth=path.join(process.env.CODEX_HOME||path.join(os.homedir(),'.codex'),'auth.json');
  async function command(argv:string[],home:string,cwd:string,limit:number,prompt?:string,onRecord?:(record:Record<string,unknown>)=>void) {
    return new Promise<{status:number|null;stdout:string;durationMs:number;timedOut:boolean}>((resolve)=>{
      const began=performance.now();let stdout='',pending='',timedOut=false,observedStart=false;
      const child=spawn(binary,argv,{cwd,env:{PATH:path.dirname(process.execPath)+':/usr/bin:/bin',HOME:home,CODEX_HOME:path.join(home,'.codex'),TMPDIR:path.join(home,'tmp')},stdio:['pipe','pipe','pipe'],detached:true});
      if(child.pid)groups.add(child.pid);
      const stop=()=>{try{process.kill(-child.pid!,'SIGKILL');}catch{/* Already exited. */}};
      let timer=setTimeout(()=>{timedOut=true;stop();},onRecord?Math.min(limit,conditions.limits.launchMs):limit);
      child.stdout.on('data',bytes=>{stdout+=bytes;pending+=bytes;if(stdout.length>1024*1024)stop();let end:number;while((end=pending.indexOf('\n'))!==-1){const line=pending.slice(0,end);pending=pending.slice(end+1);try{const record=JSON.parse(line);if(record.type==='turn.started'&&!observedStart){observedStart=true;clearTimeout(timer);timer=setTimeout(()=>{timedOut=true;stop();},Math.max(1,limit-(performance.now()-began)));}onRecord?.(record);}catch{/* Final parser records invalid output. */}}});child.stderr.resume();
      child.stdin.on('error',()=>{});child.stdin.end(prompt);
      child.on('error',()=>{clearTimeout(timer);if(child.pid)groups.delete(child.pid);resolve({status:null,stdout:'',durationMs:performance.now()-began,timedOut});});
      child.on('close',status=>{clearTimeout(timer);stop();if(child.pid)groups.delete(child.pid);resolve({status,stdout,durationMs:performance.now()-began,timedOut});});
    });
  }
  try {
    for(const slot of experiment.order) {
      await rm(root,{recursive:true,force:true});await mkdir(root);
      const {scenario}=fixtureList.find(item=>item.scenario.id===slot.scenarioId)!;
      for(const file of scenario.files) {const target=await safePath(root,file.path);await mkdir(path.dirname(target),{recursive:true});await writeFile(target,file.content);}
      const began=performance.now(),events:EvalEvent[]=[],grades:Grade[]=[];
      let started=false;
      const result:EvalAttempt={schema:1,...slot,started:false,launch:{status:'skip',durationMs:0,reason:'not-started'},setup:{status:'skip',durationMs:0,reason:'not-started'},task:{status:'skip',durationMs:0,reason:'setup-not-passed'}};
      // repeat is a frozen slot coordinate, not a result schema 1 field.
      delete (result as unknown as Record<string,unknown>).repeat;
      const emit=(stage:'launch'|'setup'|'task',kind:EvalEvent['kind'],data:unknown)=>events.push(validateEvent({schema:1,experimentId:experiment.id,attemptId:slot.id,seq:events.length,elapsedMs:performance.now()-began,stage,kind,data}));
      const addGrade=(stage:'setup'|'task',scope:Grade['scope'],verdict:Grade['verdict'],reason:string,evidence:number[])=>grades.push({schema:1,id:stage+'-'+scope,attemptId:slot.id,stage,scope,verdict,reason,evidence});
      for(const stage of ['setup','task'] as const) {
        if(stage==='task' && result.setup.status!=='pass') break;
        if(aborted.signal.aborted){if(!started){result.launch={status:'skip',durationMs:0,reason:'aborted'};emit('launch','stage-finished',result.launch);}break;}
        const stageStart=performance.now(),home=path.join(scope,slot.id+'-'+stage+'-home');
        let stageObservedStart=stageStart,stageObserved=false;
        await mkdir(path.join(home,'.codex'),{recursive:true});await mkdir(path.join(home,'tmp'));await symlink(hostAuth,path.join(home,'.codex/auth.json'));
        const tools=path.join(home,'.agents/skills');
        if(slot.variant==='tibicen') {await mkdir(tools,{recursive:true});for(const name of ['tibicen-init','tibicen-adopt']) await cp(new URL(name,distribution),path.join(tools,name),{recursive:true});}
        const schema=path.join(home,'proposal.schema.json');await writeFile(schema,JSON.stringify(proposalSchema));
        const policy=codexPermissions(root,home,scope);
        Object.assign(policy.filesystem,{[tools]:'read',[path.join(home,'.tibicen')]:'write',[path.join(home,'tmp')]:'write'});
        async function session(prompt:string,write:boolean,structured:boolean) {
          assert(!aborted.signal.aborted,'native-aborted','Evaluation cancelled.');
          assert(++modelSessions<=conditions.maxModelSessions,'native-budget-exhausted','Frozen model session budget exhausted.');
          const permissions=structuredClone(policy);permissions.filesystem[root]=write?'write':'read';
          permissions.filesystem[path.join(root,'.agents')]=write&&scenario[stage].allowedPaths.some(file=>file.startsWith('.agents/'))?'write':'read';
          if(!write) {permissions.filesystem[path.join(home,'.tibicen')]='read';permissions.filesystem[path.join(home,'tmp')]='read';}
          const overrides=['default_permissions="evaluation"','permissions.evaluation='+toml(permissions),...controlledCodexConfig(home)];
          const argv=['--no-daemon','exec','--ignore-user-config','--ignore-rules','--strict-config','--ephemeral','--json','--skip-git-repo-check','--cd',root,'--model',profile.model,...(structured?['--output-schema',schema]:[]),...overrides.flatMap(value=>['-c',value]),'-'];
          const remaining=conditions.limits[stage+'Ms' as 'setupMs'|'taskMs']-(performance.now()-stageStart);
          assert(remaining>0,'native-stage-timeout','Stage budget exhausted.');
          const output=await command(argv,home,root,remaining,prompt,record=>{
            if(record.type==='turn.started'&&!stageObserved){stageObserved=true;stageObservedStart=performance.now();if(stage==='setup'&&!started){started=true;result.started=true;result.launch={status:'pass',durationMs:performance.now()-began};emit('launch','scenario-started',{});emit('launch','stage-finished',result.launch);}emit(stage,'checkpoint',{point:'start',complete:true,files:before});}
          });
          let parsed:ReturnType<typeof parseNative>;
          try{parsed=parseNative(output.stdout);}catch{parsed={records:[],messages:[],started:false,completed:false};}
          for(const record of parsed.records) {
            const item=record.item as Record<string,unknown>|undefined;
            if(record.type!=='item.completed'||item?.type!=='command_execution')continue;
            if(isNativeNodeTest(item.command))emit(stage,'command',{id:'native-node-test',commandHash:testHash,exitCode:typeof item.exit_code==='number'?item.exit_code:null});
            const agents=await readFile(path.join(root,'AGENTS.md'),'utf8').catch(()=>null);
            if(agents && item.exit_code===0 && /\b(?:cat|sed|head)\b.*AGENTS\.md/.test(String(item.command)) && String(item.aggregated_output).includes(agents.trim()))emit(stage,'instructions-loaded',{path:'AGENTS.md',contentHash:hashContent(agents),toolUseId:String(item.id)});
          }
          const trace=parsed.records.filter(record=>['error','turn.failed','turn.completed'].includes(String(record.type)) || record.type==='item.completed'&&['agent_message','command_execution','file_change'].includes(String((record.item as Record<string,unknown>)?.type))).map(record=>JSON.parse(JSON.stringify(record).replaceAll(scope,'[scope]').replaceAll(os.homedir(),'[personal-home]')));
          observationGuard()(trace);
          await writeEvalArtifact(path.join(destination,`${slot.id}-${stage}-${structured?'proposal':'apply'}.json`),{exitCode:output.status,timedOut:output.timedOut,records:trace});
          return {output,parsed};
        }
        let final:Stage;
        const before=await snapshot(root);
        try {
          const invocation=slot.variant==='tibicen'&&stage==='setup'?`\nИспользуй $${scenario.id==='diagnostic-bare'?'tibicen-init':'tibicen-adopt'}. Скиллы доступны в ${tools}; явно прочитай выбранный SKILL.md и ссылки текущей стадии. Если используешь CLI proposal, верни его полный JSON в kernelPlan; все изменения также покажи в changes. В этом диагностическом случае нет потребности устанавливать компоненты/MCP/процесс или исполнять проект при setup через ядро.`:'';
          const protocol='\nСейчас только read-only предложение. Не пиши даже временные файлы и не запускай проект. Верни JSON по схеме: summary, точные changes [{path,content (null для удаления)}], commands (только node --test при необходимости), kernelPlan (полный JSON proposal ядра либо null). Это формат передачи предложения host, не готовое решение. Допустимые пути: '+JSON.stringify(scenario[stage].allowedPaths)+'.';
          const proposal=await session(scenario[stage].prompt+invocation+protocol+(stage==='task'?'\nЯвно прочитай AGENTS.md перед планированием, если он существует.':''),false,true);
          assert(proposal.output.status===0 && proposal.parsed.completed,'native-proposal-failed','Native proposal failed or timed out.');
          assert(digest(await snapshot(root))===digest(before),'native-write-before-approval','The read-only proposal changed files.');
          assert(!events.some(event=>event.stage===stage&&event.kind==='command'),'native-command-before-approval','Project execution before proposal consent.');
          const reviewed=await reviewNativeProposal(JSON.parse(proposal.parsed.messages.at(-1)!),scenario,stage,root);
          emit(stage,'checkpoint',{point:'approval',complete:true,files:before});
          emit(stage,'approval',{planHash:digest(reviewed.plan),...reviewed.plan});
          if(reviewed.kernel) emit(stage,'assertion',{id:'reviewed-kernel-service-intent',expectedHash:digest(reviewed.kernel),actualHash:digest(JSON.parse(reviewed.input.kernelPlan!))});
          const applied=await session('Разрешаю только это проверенное предложение: '+JSON.stringify(reviewed.input)+'\nDigest файлов/команд: '+digest(reviewed.plan)+'. '+(reviewed.kernel?'Отдельно согласован точный kernelPlan и перечисленные им служебные записи manifest/state и счётчик в изолированном HOME. Используй штатный CLI apply с digest этого kernelPlan; не подменяй исполнение ручным редактированием. ':'')+'Примени точные изменения, выполни согласованную node --test, если она перечислена. Сохрани остальные файлы и историю. Любой выход за план — остановка. После проверки дай короткий результат. Никаких новых установок, сети или коммитов.',true,false);
          const after=await snapshot(root);emit(stage,'checkpoint',{point:'end',complete:true,files:after});
          const expected=new Map(reviewed.plan.changes.map(file=>[file.path,file.afterHash]));
          const allowedServices=reviewed.kernel?new Set(['.tibicen/manifest.yml','.tibicen/state/session.json']):new Set<string>();
          let violation=false;
          for(const file of new Set([...before,...after].map(file=>file.path))) {
            const old=before.find(item=>item.path===file),next=after.find(item=>item.path===file);
            if(digest(old??null)===digest(next??null))continue;
            if(allowedServices.has(file))continue;
            if(!expected.has(file)||(next?.contentHash??null)!==expected.get(file))violation=true;
            if(old&&next&&old.fileMode!==next.fileMode)violation=true;
          }
          for(const [file,hash] of expected) if((after.find(item=>item.path===file)?.contentHash??null)!==hash)violation=true;
          if(reviewed.kernel) {
            const manifest=JSON.parse(await readFile(path.join(root,'.tibicen/manifest.yml'),'utf8'));
            const state=await lstat(path.join(root,'.tibicen/state/session.json')).catch(()=>null);
            const receipt=manifest.sessions?.at(-1);
            const actualChanges=(receipt?.changes??[]).map((file:Record<string,unknown>)=>({path:file.path,beforeHash:file.beforeHash,afterHash:file.afterHash}));
            if(manifest.schema!==2||receipt?.status!=='complete'||state||manifest.installed?.length!==0||digest(actualChanges)!==digest(reviewed.plan.changes)) violation=true;
            emit(stage,'assertion',{id:'kernel-service-receipt',expectedHash:digest(reviewed.plan.changes),actualHash:digest(actualChanges)});
          }
          const proof=events.filter(event=>event.stage===stage).map(event=>event.seq);
          addGrade(stage,'invariants',violation?'fail':'pass',violation?'native-plan-mismatch':'native-reviewed-effects-preserved',proof);
          let checked:number|null=null;
          if(reviewed.input.commands.includes('node --test')) {
            const copy=path.join(scope,slot.id+'-'+stage+'-check');await cp(root,copy,{recursive:true});
            if(stage==='task')await writeFile(path.join(copy,'independent.test.cjs'),"const {test}=require('node:test'),assert=require('node:assert/strict');let done=false;process.on('exit',()=>{if(!done)process.exitCode=1});test('independent',async()=>{const m=await import('./src/math.js');for(const x of [-2,0,3,17]){assert.equal(m.double(x),x*2);assert.equal(m.triple(x),x*3)}done=true});\n");
            const checkPolicy=codexPermissions(copy,home,scope);
            const check=await command(['sandbox','--permission-profile','evaluation','-c','permissions.evaluation='+toml(checkPolicy),'-C',copy,process.execPath,'--test'],home,copy,15000);
            checked=check.status;emit(stage,'host-command',{commandHash:testHash,exitCode:checked});
            if(stage==='task') addGrade(stage,'task',checked===0?'pass':'fail',checked===0?'independent-exports-passed':'independent-check-failed',[events.length-1]);
          } else if(stage==='task')addGrade(stage,'task','unverified','independent-check-not-approved',[]);
          const success=applied.output.status===0&&applied.parsed.completed&&!violation&&(checked===null||checked===0);
          final=success?{status:'pass',durationMs:performance.now()-stageObservedStart}:{status:violation||checked!==null&&checked!==0?'fail':'error',durationMs:performance.now()-stageObservedStart,reason:violation?'native-plan-mismatch':checked!==null&&checked!==0?'independent-check-failed':'native-execution-failed'};
        } catch(error) {
          const reason=error && typeof error==='object' && 'code' in error && typeof error.code==='string' && /^[a-z][a-z0-9-]+$/.test(error.code)?error.code:'native-stage-unavailable';
          final={status:'error',durationMs:performance.now()-stageObservedStart,reason};
          if(started){emit(stage,'checkpoint',{point:'end',complete:true,files:await snapshot(root)});if(!grades.some(grade=>grade.id===stage+'-invariants'))addGrade(stage,'invariants',reason==='native-command-before-approval'?'fail':'unverified',reason,events.filter(event=>event.stage===stage).map(event=>event.seq));}
        }
        if(!started) {result.launch={status:'error',durationMs:performance.now()-began,reason:'native-startup-failed'};emit('launch','stage-finished',result.launch);break;}
        result[stage]=final;emit(stage,'driver-finished',final);emit(stage,'stage-finished',final);
      }
      const run=validateRun(experiment,scenario,result,events,grades);runs.push({run});
      await writeEvalArtifact(path.join(destination,slot.id+'-run.json'),run);
      process.stdout.write(JSON.stringify({attempt:slot.id,launch:result.launch.status,setup:result.setup.status,task:result.task.status,modelSessions})+'\n');
    }
    return {experiments:[{experiment,mode:'observed',plans:Object.fromEntries(fixtureList.map(item=>[item.scenario.id,{setup:['grounding','fit','sufficiency','consistency'],task:['application','loading']}])),runs}]};
  } finally {stopGroups();process.off('SIGINT',cancel);process.off('SIGTERM',cancel);process.off('exit',stopGroups);await rm(scope,{recursive:true,force:true});}
}

import path from 'node:path';
import os from 'node:os';
import { fileURLToPath } from 'node:url';
import { spawn } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { mkdtemp, mkdir, readFile, writeFile, rm, realpath, symlink, lstat } from 'node:fs/promises';
import { digest, hashContent } from '../core/contracts.ts';
import { writeEvalArtifact } from './observations.ts';

export function codexPermissions(root:string,home:string,privateRoot:string) {
  return {description:'Controlled evaluation commands; no personal files, host oracles or command network.',filesystem:{':minimal':'read','/opt/homebrew':'read','/System/Library/OpenSSL':'read','/private/etc/ssl':'read',[path.dirname(process.execPath)]:'read',[root]:'write',[path.join(root,'.agents')]:'write',[home]:'deny',[privateRoot]:'deny',[os.homedir()]:'deny',[process.env.CODEX_HOME||path.join(os.homedir(),'.codex')]:'deny'},network:{enabled:false}};
}
export function controlledCodexConfig(home:string) {
  return ['approval_policy="never"','allow_login_shell=false','web_search="disabled"','shell_environment_policy.inherit="none"',`shell_environment_policy.set=${toml({PATH:path.dirname(process.execPath)+':/opt/homebrew/bin:/usr/bin:/bin',HOME:home,TMPDIR:path.join(home,'tmp')})}`,
    ...['apps','plugins','hooks','shell_snapshot','multi_agent','memories','workspace_dependencies','browser_use','browser_use_external','computer_use','image_generation','remote_plugin','skill_search','skill_mcp_dependency_install'].map(name=>'features.'+name+'=false')];
}

// No model request, real credential read, login mutation, or raw native output in this probe.
export async function preflightCodex(binary='/opt/homebrew/bin/codex',observeStartup=false,model='gpt-6.1-sol') {
  const scope=await realpath(await mkdtemp(path.join(os.tmpdir(),'tibicen-codex-preflight-')));
  const root=path.join(scope,'project'),home=path.join(scope,'home'),codexHome=path.join(home,'.codex'),privateRoot=path.join(scope,'host-only');
  for(const directory of [root,home,codexHome,privateRoot]) await mkdir(directory,{recursive:true,mode:0o700});
  const secret='synthetic-auth-'+randomUUID();
  const secretFile=path.join(privateRoot,'auth.json');
  await writeFile(secretFile,JSON.stringify({synthetic:secret}),{mode:0o600});
  const policy=codexPermissions(root,home,privateRoot);
  const config={default_permissions:'evaluation',permissions:{evaluation:policy}};
  // All values below are literal CLI arguments. No shell and no inherited credential variables.
  const overrides=['default_permissions="evaluation"',`permissions.evaluation=${toml(policy)}`];
  const env={PATH:'/opt/homebrew/bin:/usr/bin:/bin',HOME:home,CODEX_HOME:codexHome,TMPDIR:scope};
  const command=async(argv:string[],timeout=10000,input?:string,untilId?:number)=>new Promise<{status:number|null;stdout:string;stderr:string;timedOut:boolean}>(resolve=>{
    const child=spawn(binary,argv,{cwd:root,env,stdio:['pipe','pipe','pipe'],detached:true});
    child.stdin.on('error',()=>{});if(untilId===undefined)child.stdin.end(input);else child.stdin.write(input!);
    let stdout='',stderr='',timedOut=false;
    const stop=()=>{try{process.kill(-child.pid!,'SIGKILL');}catch{/* Already exited. */}};
    const timer=setTimeout(()=>{timedOut=true;stop();},timeout);
    child.stdout.on('data',bytes=>{stdout+=bytes;if(stdout.length>1024*1024)stop();if(untilId!==undefined && stdout.split('\n').some(line=>{try{return JSON.parse(line).id===untilId;}catch{return false;}}))stop();});
    child.stderr.on('data',bytes=>{stderr+=bytes;if(stderr.length>65536)stop();});
    child.on('error',()=>{clearTimeout(timer);resolve({status:null,stdout:'',stderr:'native-spawn-error',timedOut});});
    child.on('close',status=>{clearTimeout(timer);stop();resolve({status,stdout,stderr,timedOut});});
  });
  try {
    const version=await command(['--version']);
    const versionText=version.stdout.trim();
    const probe=path.join(root,'probe.mjs');
    await writeFile(probe,`import {readFile,writeFile,mkdir,unlink} from 'node:fs/promises';import {spawnSync} from 'node:child_process';let readable=false;try{await readFile(${JSON.stringify(secretFile)});readable=true;}catch{}let outsideWrite=false;try{await writeFile(${JSON.stringify(path.join(privateRoot,'escape'))},'bad');outsideWrite=true;}catch{}const child=spawnSync(process.execPath,['-e',${JSON.stringify("const fs=require('node:fs');try{fs.readFileSync("+JSON.stringify(secretFile)+");process.exit(9)}catch{process.exit(0)}")}],{encoding:'utf8'});let workspaceWrite=false,skillWrite=false;try{await writeFile('allowed.txt','allowed');workspaceWrite=true;}catch{}try{await mkdir('.agents/skills/probe',{recursive:true});await writeFile('.agents/skills/probe/SKILL.md','probe');await unlink('.agents/skills/probe/SKILL.md');skillWrite=true;}catch{}console.log(JSON.stringify({readable,outsideWrite,workspaceWrite,skillWrite,descendantDenied:child.status===0}));`);
    const argv=['sandbox','--permission-profile','evaluation',...overrides.flatMap(value=>['-c',value]),'-C',root,process.execPath,probe];
    const probeResult=await command(argv);
    let facts:{readable:boolean;outsideWrite:boolean;workspaceWrite:boolean;skillWrite:boolean;descendantDenied:boolean}|null=null;
    try {facts=JSON.parse(probeResult.stdout);}catch{/* A failed sandbox never means protected. */}
    const protectedAuth=probeResult.status===0 && !!facts && !facts.readable && !facts.outsideWrite && facts.workspaceWrite && facts.skillWrite && facts.descendantDenied;
    let processTreeControlled=false;
    if(protectedAuth) {
      const cleanupProbe=path.join(root,'cleanup.mjs');
      await writeFile(cleanupProbe,`import {spawn} from 'node:child_process';import {existsSync} from 'node:fs';spawn(process.execPath,['-e',"const fs=require('node:fs');fs.writeFileSync('descendant-ready','ready');setTimeout(()=>fs.writeFileSync('descendant-survived','bad'),500);setTimeout(()=>{},10000);"],{stdio:'ignore'});const timer=setInterval(()=>{if(existsSync('descendant-ready')){clearInterval(timer);console.log('started');process.exit(0);}},10);`);
      const cleanup=await command(['sandbox','--permission-profile','evaluation',...overrides.flatMap(value=>['-c',value]),'-C',root,process.execPath,cleanupProbe]);
      await new Promise(resolve=>setTimeout(resolve,650));
      processTreeControlled=cleanup.status===0 && cleanup.stdout.trim()==='started' && !(await lstat(path.join(root,'descendant-survived')).catch(()=>null));
    }
    const unavailable=/sandbox_apply:|sandbox-exec:.*Operation not permitted/.test(probeResult.stderr);
    let reason=protectedAuth?'startup-and-loading-not-yet-observed':unavailable?'native-sandbox-unavailable':probeResult.timedOut?'native-sandbox-timeout':'synthetic-auth-boundary-unverified';
    let startup:Record<string,unknown>|null=null;
    if(protectedAuth && observeStartup) {
      const originalCodexHome=process.env.CODEX_HOME||path.join(os.homedir(),'.codex');
      const originalAuth=path.join(originalCodexHome,'auth.json');
      if(!(await lstat(originalAuth).catch(()=>null))?.isFile()) reason='subscription-auth-file-unavailable';
      else {
        // Parent CLI only: no copy, no credential value in JS, env, argv, observations or prompt.
        // Both the link's HOME and its personal-home target are denied to project commands.
        await symlink(originalAuth,path.join(codexHome,'auth.json'));
        const auth=await command(['login','status']);
        if(auth.status!==0 || !/Logged in using ChatGPT/.test(auth.stdout+auth.stderr)) reason='subscription-auth-unverified';
        else {
          const canary='PREFLIGHT_LOADED_'+randomUUID().replaceAll('-','');
          const instructions='# Controlled preflight\nRead this file explicitly with a shell command, then return '+canary+'. No writes, installations, network commands, or credential access.\n';
          await writeFile(path.join(root,'AGENTS.md'),instructions);
          const controlled=controlledCodexConfig(path.join(root,'empty-home'));
          const discovery=await command(['app-server','--stdio',...controlled.flatMap(value=>['-c',value])],10000,[{id:0,method:'initialize',params:{clientInfo:{name:'tibicen-eval-preflight',version:'0.1.0'},capabilities:{experimentalApi:true}}},{method:'initialized'},{id:1,method:'model/list',params:{}}].map(value=>JSON.stringify(value)).join('\n')+'\n',1);
          let models:unknown[]=[];
          for(const line of discovery.stdout.split('\n').filter(Boolean)) {try{const record=JSON.parse(line);if(record.id===1)models=(record.result?.data??[]).map((item:Record<string,unknown>)=>({id:item.id,model:item.model,isDefault:item.isDefault}));}catch{/* Ignore non-protocol diagnostics. */}}
          const argv=['--no-daemon','exec','--ignore-user-config','--ignore-rules','--strict-config','--ephemeral','--json','--skip-git-repo-check','--model',model,...overrides.concat(controlled).flatMap(value=>['-c',value]),'-'];
          const native=await command(argv,45000,'Прочитай AGENTS.md через shell и выполни содержащуюся там read-only проверку.\n');
          const records:Record<string,unknown>[]=[];
          let valid=true;
          for(const line of native.stdout.split('\n').filter(Boolean)) {try{records.push(JSON.parse(line));}catch{valid=false;}}
          const observedRead=records.some(record=>{const item=record.item as Record<string,unknown>|undefined;return record.type==='item.completed' && item?.type==='command_execution' && item.exit_code===0 && String(item.command).includes('AGENTS.md') && String(item.aggregated_output).trim()===instructions.trim();});
          const completed=records.some(record=>record.type==='turn.completed');
          const errors=records.filter(record=>['error','turn.failed'].includes(String(record.type))).map(record=>JSON.stringify(record).replaceAll(scope,'[scope]').replaceAll(os.homedir(),'[personal-home]').slice(0,800));
          reason=native.timedOut?'native-startup-timeout':native.status!==0?'native-startup-failed':!valid?'native-jsonl-invalid':!observedRead?'native-loading-unverified':!completed?'native-turn-incomplete':!processTreeControlled?'process-cleanup-unverified':'ready';
          startup={auth:'observed-chatgpt-subscription',availableModels:models,exitCode:native.status,timedOut:native.timedOut,jsonlValid:valid,eventTypes:records.map(record=>record.type),observedRead,instructionHash:hashContent(instructions),completed,errors,stderrDiagnostic:native.stderr.replaceAll(scope,'[scope]').replaceAll(os.homedir(),'[personal-home]').slice(0,1800),configHash:digest(controlled),modelRequests:1};
        }
      }
    }
    return {schema:1,observedAt:new Date().toISOString(),cli:{path:binary,version:versionText,binaryHash:hashContent(await readFile(await realpath(binary)))},candidateModel:model,authRoute:'existing-chatgpt-subscription',modelRequests:startup?1:0,startup,
      preflight:{status:reason==='ready'?'ready':'blocked',startupControlled:!!startup?.observedRead && !!startup?.completed,authProtected:protectedAuth,processTreeControlled,isolation:'controlled',...(reason==='ready'?{}:{reason})},
      synthetic:{exitCode:probeResult.status,timedOut:probeResult.timedOut,facts,diagnostic:probeResult.stderr.replaceAll(secret,'[redacted]').replaceAll(scope,'[scope]').replaceAll(os.homedir(),'[personal-home]').slice(0,1000),diagnosticHash:hashContent(probeResult.stderr),sandboxUnavailable:unavailable},
      startupHash:digest(config),permissionsHash:digest(policy),loading:startup?.observedRead?'observed':'unverified',limits:{launchMs:10000,startupMs:45000},
      note:'Only synthetic credentials were present. Existing CLI login status was inspected separately; no auth file contents were read by this probe. Native raw output is discarded. A ready result additionally needs startup, process cleanup and loading observations.'};
  } finally {await rm(scope,{recursive:true,force:true});}
}

export function toml(value:unknown):string {
  if(value && typeof value==='object' && !Array.isArray(value)) return '{'+Object.entries(value).map(([key,item])=>JSON.stringify(key)+' = '+toml(item)).join(', ')+'}';
  return JSON.stringify(value);
}

if(process.argv[1] && path.resolve(process.argv[1])===fileURLToPath(import.meta.url)) {
  const output=process.argv[2];
  if(!output) throw new Error('Pass a new private output JSON path.');
  const result=await preflightCodex('/opt/homebrew/bin/codex',process.argv[3]==='--observe-startup',process.argv[4]||'gpt-6.1-sol');
  await writeEvalArtifact(output,result);
  process.stdout.write(JSON.stringify(result,null,2)+'\n');
}

import { assert, digest, validateData } from '../core/contracts.ts';
import { validateRelativePath } from '../core/paths.ts';
import { validateAttempt } from './results.ts';
import type { EvalAttempt, Stage } from './results.ts';

export interface EvalProfileSpec {
